function NetworkSphere() {
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  return <motion.div className="sphere-stage relative mx-auto aspect-square w-full max-w-[340px] sm:max-w-[460px] lg:max-w-[540px]" animate={{ y: [0, -8, 0] }} transition={{ duration: 7.5, repeat: Infinity, ease: "easeInOut" }} onPointerMove={(event) => { const rect = event.currentTarget.getBoundingClientRect(); setTilt({ x: ((event.clientY - rect.top) / rect.height - 0.5) * -10, y: ((event.clientX - rect.left) / rect.width - 0.5) * 10 }); }} onPointerLeave={() => setTilt({ x: 0, y: 0 })} data-testid="hero-network-sphere">
    <motion.div className="sphere-core" animate={{ rotate: 360 }} transition={{ duration: 3.6, repeat: Infinity, ease: "linear" }} style={{ rotateX: tilt.x, rotateY: tilt.y }}>
      <div className="sphere-ring ring-one" /><div className="sphere-ring ring-two" /><div className="sphere-ring ring-three" /><div className="sphere-ring ring-four" />
      <div className="sphere-grid" /><div className="sphere-glow" />
      <div className="sphere-node node-a" /><div className="sphere-node node-b" /><div className="sphere-node node-c" /><div className="sphere-node node-d" />
      <div className="sphere-logo-mark"><img src="/zylo-core-mark.png" alt="Zylo Core mark" /></div>
    </motion.div>
    {heroCapabilities.map(({ label, icon: Icon, top, left, color, motion: floatMotion }, index) => <motion.button type="button" key={label} onClick={() => label === "Secure" && window.dispatchEvent(new CustomEvent("open-security-layer"))} className="sphere-badge" style={{ top, left, "--badge-accent": color } as CSSProperties} animate={{ y: [...floatMotion] }} transition={{ duration: 2.1 + index * 0.16, repeat: Infinity, ease: "easeInOut" }} data-testid={`hero-${label.toLowerCase().replaceAll(" ", "-")}-node`}><Icon size={17} /><span>{label}</span></motion.button>)}
    <span className="sphere-caption" data-testid="hero-sphere-caption">ZYLO CORE / 01 · LIVE SYSTEM</span>
  </motion.div>;
}

