function SecurityLayerVisual({ selected, onSelect }: { selected: string; onSelect: (layer: string) => void }) {
  const layers = [
    ["Internet", "External traffic / identity requests", "#60a5fa", "Global traffic enters through controlled gateways and policy checks."],
    ["Firewall", "Perimeter policy / segmentation", "#22d3ee", "Blocks unwanted traffic, separates zones, and enforces network policy."],
    ["Threat Detection", "Signals / anomaly analysis", "#f472b6", "Correlates events and flags suspicious behavior before it spreads."],
    ["Zero Trust", "Verify every request", "#a78bfa", "Identity, device posture, and context are evaluated continuously."],
    ["Encryption", "Data in transit / at rest", "#facc15", "Protects sensitive information with strong encryption and key controls."],
    ["Data / AI", "Protected business intelligence", "#34d399", "Turns trusted security and business signals into safe decisions."],
  ] as const;
  const active = layers.find(([name]) => name === selected) ?? layers[1];
  return <div className="security-visual" data-testid="security-layer-visual">
    <div className="security-scanline" />
    <div className="security-ring security-ring-a" /><div className="security-ring security-ring-b" /><div className="security-ring security-ring-c" />
    <div className="security-center"><ShieldCheck size={42} strokeWidth={1.15} /><span>ZERO TRUST</span><small>LIVE DEFENSE MESH</small></div>
    <div className="security-links">{layers.slice(0, -1).map(([name, , color], index) => <span key={name} className={`security-link security-link-${index + 1}`} style={{ "--security-color": color } as CSSProperties} />)}</div>
    {layers.map(([name, sub, color]) => <button key={name} type="button" onClick={() => onSelect(name)} className={`security-node security-node-${name.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")} ${selected === name ? "is-active" : ""}`} style={{ "--security-color": color } as CSSProperties}>
      <span className="security-node-dot" /><strong>{name}</strong><small>{sub}</small>
    </button>)}
    <div className="security-detail" style={{ "--security-color": active[2] } as CSSProperties}>
      <span className="font-mono text-[9px] uppercase tracking-[0.18em]">Selected layer</span>
      <strong>{active[0]}</strong><p>{active[3]}</p>
      <span className="security-pulse"><i /> Protection active</span>
    </div>
  </div>;
}

function AppButton({ children, onClick, variant = "primary", testId }: { children: ReactNode; onClick?: () => void; variant?: "primary" | "outline"; testId: string }) {
  return <Button onClick={onClick} variant={variant === "primary" ? "default" : "outline"} className={variant === "primary" ? "group h-12 rounded-none border border-cyan-300/50 bg-cyan-300 px-5 font-mono text-[11px] font-bold uppercase tracking-[0.16em] text-slate-950 shadow-[0_0_30px_rgba(34,211,238,0.2)] hover:bg-cyan-200" : "group h-12 rounded-none border-white/15 bg-white/[0.03] px-5 font-mono text-[11px] font-bold uppercase tracking-[0.16em] text-white hover:border-cyan-300/60 hover:bg-cyan-300/10"} data-testid={testId}>{children}<ArrowUpRight className="ml-3 size-4 transition-transform duration-300 group-hover:translate-x-1 group-hover:-translate-y-1" /></Button>;
}

function DetailDialog({ open, onClose, eyebrow, title, description, columns, primaryLabel, onPrimary, testId }: { open: boolean; onClose: () => void; eyebrow: string; title: string; description: string; columns: { title: string; items: string[] }[]; primaryLabel: string; onPrimary: () => void; testId: string }) {
  return <Dialog open={open} onOpenChange={(isOpen) => { if (!isOpen) onClose(); }}><DialogContent showCloseButton={false} className="max-h-[88vh] max-w-3xl overflow-y-auto rounded-none border-cyan-300/25 bg-[#070b15]/98 p-0 text-slate-100 shadow-[0_0_90px_rgba(6,182,212,0.16)] backdrop-blur-2xl" data-testid={testId}><div className="relative overflow-hidden border-b border-white/10 p-7 sm:p-10"><div className="tech-grid absolute inset-0 opacity-25" /><button onClick={onClose} className="absolute right-5 top-5 z-10 flex size-10 items-center justify-center border border-white/10 bg-black/20 text-slate-400 hover:border-cyan-300/50 hover:text-cyan-200" aria-label="Close details" data-testid={`${testId}-close-button`}><X size={17} /></button><DialogHeader className="relative pr-12"><p className="font-mono text-[10px] uppercase tracking-[0.24em] text-cyan-300" data-testid={`${testId}-eyebrow`}>{eyebrow}</p><DialogTitle className="mt-4 font-heading text-3xl font-medium tracking-[-0.05em] text-white sm:text-5xl" data-testid={`${testId}-title`}>{title}</DialogTitle><DialogDescription className="mt-5 max-w-2xl text-sm leading-7 text-slate-400 sm:text-base" data-testid={`${testId}-description`}>{description}</DialogDescription></DialogHeader></div><div className="grid gap-0 sm:grid-cols-2" data-testid={`${testId}-content`}>{columns.map((column, columnIndex) => <div key={column.title} className={`p-7 sm:p-9 ${columnIndex === 0 ? "border-b border-white/10 sm:border-b-0 sm:border-r" : ""}`} data-testid={`${testId}-column-${columnIndex + 1}`}><h4 className="font-mono text-[10px] uppercase tracking-[0.2em] text-slate-500" data-testid={`${testId}-column-${columnIndex + 1}-title`}>{column.title}</h4><div className="mt-5 space-y-3">{column.items.map((item, itemIndex) => <div key={item} className="flex items-start gap-3 text-sm leading-6 text-slate-300" data-testid={`${testId}-column-${columnIndex + 1}-item-${itemIndex + 1}`}><span className="mt-2 size-1.5 shrink-0 rounded-full bg-cyan-300 shadow-[0_0_8px_#67e8f9]" />{item}</div>)}</div></div>)}</div><div className="flex flex-col gap-4 border-t border-white/10 bg-white/[0.02] p-7 sm:flex-row sm:items-center sm:justify-between sm:px-9"><p className="font-mono text-[9px] uppercase tracking-[0.18em] text-slate-600" data-testid={`${testId}-footer-note`}>Ganesh Tech / solution brief</p><Button onClick={onPrimary} className="group h-11 rounded-none bg-cyan-300 px-5 font-mono text-[10px] font-bold uppercase tracking-[0.15em] text-slate-950 hover:bg-cyan-200" data-testid={`${testId}-primary-button`}>{primaryLabel}<ArrowRight size={15} className="ml-3 transition-transform duration-300 group-hover:translate-x-1" /></Button></div></DialogContent></Dialog>;
}

